void setup() {
  pinMode(LED_PIN, OUTPUT);
  pinMode(BTN_PIN, INPUT_PULLUP);   // 내부 저항으로 기본값을 HIGH 로
}
void loop() {
  bool pressed = digitalRead(BTN_PIN) == LOW;   // 눌리면 GND 로 떨어진다
  digitalWrite(LED_PIN, pressed ? HIGH : LOW);
}

unsigned long lastChange = 0;
bool stable = HIGH;
void loop() {
  bool now = digitalRead(BTN_PIN);
  if (now != stable && millis() - lastChange > 30) {   // 30ms 안정화
    stable = now; lastChange = millis();
    if (stable == LOW) onPressed();
  }
}
